          fill='none'
          strokeWidth={STROKE_WIDTH}
          strokeLinecap='round'
          strokeLinejoin='round'
          aria-hidden='true'
          className='size-full **:[vector-effect:non-scaling-stroke]'
        >
          <path d='M48 20V12' className={OUTLINE} />
          <circle
            cx='48'
            cy='9'
            r='3.5'
            className='fill-primary stroke-primary'
          />
          <rect x='7' y='41' width='7' height='18' rx='3.5' className={PLATE} />
          <rect
            x='82'
            y='41'
            width='7'
            height='18'
            rx='3.5'
            className={PLATE}
          />
          <rect
            x='14'
            y='20'
            width='68'
            height='58'
            rx='20'
            className={PLATE}
          />
          <rect
            x='24'
            y='36'
            width='48'
            height='24'
            rx='12'
            className={VISOR}
          />
          <g className={EYES_FOLLOW_GAZE}>
            <rect
              data-eye=''
              x='38'
              y='42'
              width='6'
              height='12'
              rx='3'
              className={EYE}
            />
            <rect
              data-eye=''
              x='52'
              y='42'
              width='6'
              height='12'
              rx='3'
              className={EYE}
            />
          </g>
          <path d='M41 68q7 4.5 14 0' className={OUTLINE} />
        </svg>
      </div>
      <div className='flex flex-col'>
        <p className='text-[13px] font-medium'>{HERO.agentName}</p>
        <p className='text-muted-foreground text-xs'>{HERO.agentRole}</p>
      </div>
    </div>
  );
}

'use client';

import { type RefObject, useEffect } from 'react';

import { type Gaze, GLANCES } from './data';

/** How far the eyes travel from the middle, in the units of the drawing: about three pixels on screen. */
const MAX_SHIFT = 2;

/** A pointer this far from the face makes the eyes look as far as they go. */
const FULL_LOOK_PX = 220;

const GLANCE_EVERY_MS = 1900;

const BLINK_GAPS_MS = [3200, 2400, 4200, 2900];

const BLINK_MS = 160;

const BLINK_FRAMES = [
  { transform: 'scaleY(1)' },
  { transform: 'scaleY(0.1)' },
  { transform: 'scaleY(1)' },
];

const CENTRE: Gaze = { x: 0, y: 0 };

function gazeToward(dx: number, dy: number): Gaze {
  const distance = Math.hypot(dx, dy);
  if (distance === 0) {
    return CENTRE;
  }
  const strength = Math.min(1, distance / FULL_LOOK_PX);
  const unitX = dx / distance;
  const unitY = dy / distance;
  return { x: unitX * strength, y: unitY * strength };
}

/**
 * Turns the eyes of the drawing toward the pointer while it is active. With no pointer they
 * glance about on their own, and they blink now and then. The look is written to two custom
 * properties of the drawing, never through state, so a moving pointer renders nothing.
 */
export function useGaze(
  faceRef: RefObject<SVGSVGElement | null>,
  isActive: boolean
) {
  useEffect(() => {
    const face = faceRef.current;
    if (!face || !isActive) {
      return;
    }
    const drawing: SVGSVGElement = face;
    let isFollowing = false;
    let frame = 0;
    let pointerX = 0;
    let pointerY = 0;
    let glanceIndex = 0;
    let blinkIndex = 0;
    let glanceTimer: ReturnType<typeof setTimeout> | undefined;
    let blinkTimer: ReturnType<typeof setTimeout> | undefined;

    function look(gaze: Gaze) {
      const shiftX = gaze.x * MAX_SHIFT;
      const shiftY = gaze.y * MAX_SHIFT;
      drawing.style.setProperty('--gaze-x', String(shiftX));
      drawing.style.setProperty('--gaze-y', String(shiftY));
    }

    function followPointer() {
      frame = 0;
      const box = drawing.getBoundingClientRect();
      const centreX = box.left + box.width / 2;
      const centreY = box.top + box.height / 2;
      const dx = pointerX - centreX;
      const dy = pointerY - centreY;
      look(gazeToward(dx, dy));
    }

    function onPointerMove(event: PointerEvent) {
      isFollowing = true;
      pointerX = event.clientX;
      pointerY = event.clientY;
      if (frame === 0) {
        frame = requestAnimationFrame(followPointer);
      }
    }

    function onPointerLeave() {
      isFollowing = false;
      look(CENTRE);
    }

    function glanceAbout() {
      glanceTimer = setTimeout(() => {
        if (!isFollowing) {
          const position = glanceIndex % GLANCES.length;
          look(GLANCES[position]);
          glanceIndex += 1;
        }
        glanceAbout();
      }, GLANCE_EVERY_MS);
    }

    function closeEyes() {
      const eyes = drawing.querySelectorAll('[data-eye]');
      eyes.forEach((eye) => eye.animate(BLINK_FRAMES, { duration: BLINK_MS }));
    }

    function blinkSometimes() {
      const position = blinkIndex % BLINK_GAPS_MS.length;
      const gap = BLINK_GAPS_MS[position];
      blinkIndex += 1;
      blinkTimer = setTimeout(() => {
        closeEyes();
        blinkSometimes();
      }, gap);
    }

    window.addEventListener('pointermove', onPointerMove, { passive: true });
    document.documentElement.addEventListener('pointerleave', onPointerLeave);
    glanceAbout();
    blinkSometimes();

    return () => {
      window.removeEventListener('pointermove', onPointerMove);
      document.documentElement.removeEventListener(
        'pointerleave',
        onPointerLeave
      );
      cancelAnimationFrame(frame);
      clearTimeout(glanceTimer);
      clearTimeout(blinkTimer);
      look(CENTRE);
    };
  }, [faceRef, isActive]);
}

import { cn } from '@/registry/ndeko/lib/utils';

import { PHRASES } from './data';

function caretClassOf(isLive: boolean) {
  if (isLive) {
    return 'animate-pulse';
  }
  return undefined;
}

type TypedPhraseProps = {
  phrase: string;
  typed: string;
  hasCaret: boolean;
  /** The caret only pulses while the hero is on screen. */
  isLive: boolean;
};

/**
 * Every phrase sits invisible in one grid cell, so the block always has the width and height of
 * the longest one, and the live phrase is laid out whole with the part not typed yet hidden, so
 * its lines break where they will break once it is typed. The caret takes no width.
 */
export function TypedPhrase({
  phrase,
  typed,
  hasCaret,
  isLive,
}: TypedPhraseProps) {
  const rest = phrase.slice(typed.length);

  return (
    <span className='text-primary-ink inline-grid text-start'>
      {PHRASES.map((candidate) => (
        <span
          key={candidate}
          aria-hidden='true'
          className='invisible col-start-1 row-start-1'
        >
          {candidate}
        </span>
      ))}
      <span aria-hidden='true' className='col-start-1 row-start-1'>
        {typed}
        {hasCaret && (
          <span className='relative inline-block w-0 align-baseline'>
            <span
              className={cn(
                'absolute start-0 top-[0.14em] h-[0.9em] w-[0.06em] rounded-full bg-current',
                caretClassOf(isLive)
              )}
            />
          </span>
        )}
        <span className='invisible'>{rest}</span>
      </span>
    </span>
  );
}

export type Gaze = {
  /** From -1 (far left) to 1 (far right). */
  x: number;
  /** From -1 (up) to 1 (down). */
  y: number;
};

export type PhraseView = {
  index: number;
  typed: string;
};

export const HERO = {
  titleStart: "Hi, I'm Ida. I make",
  description:
    'Pip is my assistant. Ask it about my work, my rates, or when I am free to start something with you.',
  primaryAction: 'Ask Pip',
  secondaryAction: 'See the work',
  agentName: 'Pip',
  agentRole: 'My assistant',
};

export const PHRASES = [
  'short films about rivers',
  'zines for night owls',
  'small tools for writers',
  'podcasts about maps',
];

export const INITIAL_VIEW: PhraseView = { index: 0, typed: PHRASES[0] };

export const GLANCES: Gaze[] = [
  { x: 1, y: -0.3 },
  { x: 0.7, y: 0.9 },
  { x: 0, y: 0 },
  { x: -0.8, y: 0.2 },
  { x: 0.2, y: -0.9 },
  { x: 0, y: 0 },
];
